// Channel block for email (shared: P32, P34, P35). Wraps the text in the Lumière HTML template (same look as the landing)
// and adds the legal footer (CAN-SPAM: physical address + unsubscribe link).
// Bloque de canal para email (compartido). Envuelve el texto en la plantilla HTML de Lumière (mismo estilo de la landing)
// y agrega el pie legal (CAN-SPAM: dirección física + link de baja).
// Input: { lead_id, email, asunto, mensaje (plain text, paragraphs split by a blank line), idioma ('es'|'en'), origen,
//          cta_texto? (optional button label) }
// Internal mode (P36 owner reports): interno = true, html_cuerpo (trusted HTML built by a Lumière flow), cta_url?, firma?, pie?
//   -> no lead_id needed and no unsubscribe link (it is not marketing: it goes to the owner).
// Modo interno (reportes a la dueña): sin lead_id ni link de baja (no es marketing: va para la dueña).
const i = $('When Called').first().json;
const negocio = {};
($input.first().json.values || []).slice(1).forEach(r => { if (r[0]) negocio[r[0]] = r[1] || ''; });

const txt = x => (x == null ? '' : String(x)).trim();
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const email = txt(i.email).toLowerCase();
const asunto = txt(i.asunto).slice(0, 120);
const cuerpo = txt(i.mensaje);
const lead_id = txt(i.lead_id);
const es = txt(i.idioma) !== 'en';
const errores = [];
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('email');
if (!asunto) errores.push('asunto');
if (!cuerpo) errores.push('mensaje');
const interno = i.interno === true || i.interno === 'true';
if (!lead_id && !interno) errores.push('lead_id');

// Public n8n URL ($env is blocked in Code nodes here) / URL pública de n8n ($env bloqueado en los Code nodes)
const base = String($execution.resumeUrl || '').split('webhook-waiting')[0];
const unsubscribe = `${base}webhook/lumiere-unsubscribe?id=${encodeURIComponent(lead_id)}`;
const spa = negocio.nombre || 'Lumière Aesthetics';
const site = (negocio.sitio_web || '').replace(/\/$/, '');
const wa = String(negocio.whatsapp_spa || '').replace(/\D/g, '');
const cta = txt(i.cta_texto) || (es ? 'Escríbenos por WhatsApp' : 'Message us on WhatsApp');
const ctaUrl = txt(i.cta_url) || (wa ? `https://wa.me/${wa}` : site);

// Brand tokens from the landing (css/styles.css) / Tokens de marca de la landing
const C = { canvas: '#FFFFFF', mist: '#F7F3EE', soft: '#EFE8DF', pale: '#DDD2C4', steel: '#75685C', slate: '#4A3F37', ink: '#2A2420', gold: '#B08D57' };
const SERIF = "'Libre Caslon Condensed', Georgia, 'Times New Roman', serif";
const SANS = "Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif";

// Paragraphs; the last one is dropped if it is only the signature (the template signs)
// Párrafos; se quita el último si es solo la firma (la plantilla firma)
let paras = cuerpo.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
if (paras.length > 1 && paras[paras.length - 1].replace(/[^\p{L}]/gu, '').toLowerCase() === spa.replace(/[^\p{L}]/gu, '').toLowerCase()) paras.pop();
const preheader = paras.length > 1 ? paras[1].slice(0, 110) : paras[0].slice(0, 110);
const pHtml = paras.map((p, k) => `<p style="margin:0 0 18px;font-family:${SANS};font-size:16px;line-height:1.6;color:${k === 0 ? C.ink : C.slate};">${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
const bodyHtml = interno && txt(i.html_cuerpo) ? String(i.html_cuerpo) : pHtml;
const footerNote = interno
  ? esc(txt(i.pie) || (es ? 'Informe automático del sistema.' : 'Automatic system report.'))
  : `${es ? 'Recibes este correo porque pediste información en nuestro sitio web.' : 'You are receiving this email because you requested information on our website.'}
    <a href="${esc(unsubscribe)}" style="color:${C.slate};text-decoration:underline;">${es ? 'Darme de baja' : 'Unsubscribe'}</a>`;

const html = `<!doctype html><html lang="${es ? 'es' : 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(asunto)}</title>
<link href="https://fonts.googleapis.com/css2?family=Libre+Caslon+Condensed:wght@400&family=Inter:wght@400;500&display=swap" rel="stylesheet">
</head><body style="margin:0;padding:0;background:${C.mist};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${esc(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.mist};"><tr><td align="center" style="padding:32px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:${C.canvas};border:1px solid ${C.pale};">
  <tr><td style="padding:32px 40px 24px;text-align:center;border-bottom:1px solid ${C.pale};">
    <div style="font-family:${SERIF};font-size:40px;line-height:1;letter-spacing:-0.01em;color:${C.ink};">Lumière</div>
    <div style="font-family:${SANS};font-size:11px;letter-spacing:0.3em;color:${C.steel};margin-top:6px;">AESTHETICS</div>
  </td></tr>
  <tr><td style="padding:40px 40px 8px;">${bodyHtml}</td></tr>
  <tr><td style="padding:8px 40px 36px;">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td style="background:${C.ink};">
      <a href="${esc(ctaUrl)}" style="display:inline-block;padding:16px 32px;font-family:${SANS};font-size:12px;letter-spacing:0.2em;text-transform:uppercase;color:${C.canvas};text-decoration:none;">${esc(cta)}</a>
    </td></tr></table>
    <p style="margin:28px 0 0;font-family:${SERIF};font-size:22px;line-height:1.2;color:${C.ink};">${esc(interno ? (txt(i.firma) || spa) : (negocio.nombre_asistente || 'Sofía'))}</p>
    <p style="margin:4px 0 0;font-family:${SANS};font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:${C.gold};">${esc(spa)}</p>
  </td></tr>
  <tr><td style="padding:24px 40px;background:${C.soft};font-family:${SANS};font-size:12px;line-height:1.6;color:${C.steel};">
    ${esc(spa)} · ${esc(negocio.direccion || '')}<br>
    ${footerNote}
  </td></tr>
</table></td></tr></table></body></html>`;

return [{ json: {
  lead_id, email, asunto, html, remitente: spa, origen: txt(i.origen) || 'P32',
  unsubscribe_url: interno ? '' : unsubscribe, errores, enviar: errores.length === 0 && Boolean(base)
} }];

// What the caller gets back / Lo que recibe el flujo que llamó
const m = $('Prepare Email').first().json;
const sent = $('Send via Gmail').isExecuted;
const r = sent ? ($('Send via Gmail').first().json || {}) : {};
let estado = 'error', error = '';
if (!sent) error = 'invalid: ' + (m.errores.join(',') || 'no_public_url');
else if (r.id) estado = 'sent';
else error = String((r.error && (r.error.message || r.error)) || r.message || 'gmail_error').slice(0, 200);
return [{ json: {
  ok: estado === 'sent', enviado: estado === 'sent', message_id: r.id || '', estado_entrega: estado, error,
  fecha: $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss')
} }];
